mapper.select:
SELECT COUNT(*)                                                                     AS generatedCount,
       COALESCE(SUM(CASE WHEN tc.status IN ('ACCEPTED','EDITED','REJECTED')
                        THEN 1 ELSE 0 END), 0)                                      AS reviewedCount,
       COALESCE(SUM(CASE WHEN tc.status = 'DRAFT'    THEN 1 ELSE 0 END), 0)        AS draftCount,
       COALESCE(SUM(CASE WHEN tc.status = 'ACCEPTED' THEN 1 ELSE 0 END), 0)        AS acceptedCount,
       COALESCE(SUM(CASE WHEN tc.status = 'EDITED'   THEN 1 ELSE 0 END), 0)        AS editedCount,
       COALESCE(SUM(CASE WHEN tc.status = 'REJECTED' THEN 1 ELSE 0 END), 0)        AS rejectedCount
  FROM test_case tc
 WHERE tc.created_at >= #{q.fromUtc}
   AND tc.created_at <  #{q.toUtcExclusive}

   AND tc.doc_id = #{q.docId}


   AND tc.task_id = #{q.taskId}

SELECT DATE(tc.created_at + INTERVAL 8 HOUR) AS dayKey, COUNT(*) AS generatedCount, COALESCE(SUM(CASE WHEN tc.status IN ('ACCEPTED','EDITED','REJECTED') THEN 1 ELSE 0 END), 0) AS reviewedCount, COALESCE(SUM(CASE WHEN tc.status = 'ACCEPTED' THEN 1 ELSE 0 END), 0) AS acceptedCount, COALESCE(SUM(CASE WHEN tc.status = 'EDITED' THEN 1 ELSE 0 END), 0) AS editedCount, COALESCE(SUM(CASE WHEN tc.status = 'REJECTED' THEN 1 ELSE 0 END), 0) AS rejectedCount FROM test_case tc WHERE tc.created_at >= #{q.fromUtc} AND tc.created_at < #{q.toUtcExclusive}
AND tc.doc_id = #{q.docId}
AND tc.task_id = #{q.taskId}
GROUP BY DATE(tc.created_at + INTERVAL 8 HOUR) ORDER BY dayKey

SELECT COALESCE(r.code, 'OTHER') AS code, ANY_VALUE(COALESCE(r.label, '其他原因')) AS label, COUNT(*) AS cnt FROM case_review cr LEFT JOIN reject_reason r ON r.code = cr.reject_reason_code AND r.enabled = 1 JOIN test_case tc ON tc.id = cr.case_id WHERE cr.action = 'REJECT' AND cr.created_at >= #{q.fromUtc} AND cr.created_at < #{q.toUtcExclusive}
AND tc.doc_id = #{q.docId}
AND tc.task_id = #{q.taskId}
GROUP BY COALESCE(r.code, 'OTHER') ORDER BY cnt DESC

SELECT l.task_id AS pointKey, ANY_VALUE(gt.task_no) AS taskNo, COALESCE(SUM(l.prompt_tokens), 0) AS promptTokens, COALESCE(SUM(l.completion_tokens), 0) AS completionTokens, COALESCE(SUM(l.cost_micro), 0) AS costMicro, COUNT(*) AS callCount FROM llm_call_log l LEFT JOIN gen_task gt ON gt.id = l.task_id WHERE l.created_at >= #{q.fromUtc} AND l.created_at < #{q.toUtcExclusive}
AND gt.doc_id = #{q.docId}
AND l.task_id = #{q.taskId}
GROUP BY l.task_id ORDER BY pointKey

SELECT DATE(l.created_at + INTERVAL 8 HOUR)    AS pointKey,
       COALESCE(SUM(l.prompt_tokens), 0)       AS promptTokens,
       COALESCE(SUM(l.completion_tokens), 0)   AS completionTokens,
       COALESCE(SUM(l.cost_micro), 0)          AS costMicro,
       COUNT(*)                                 AS callCount
  FROM llm_call_log l
  LEFT JOIN gen_task gt ON gt.id = l.task_id
 WHERE l.created_at >= #{q.fromUtc}
   AND l.created_at <  #{q.toUtcExclusive}

   AND gt.doc_id = #{q.docId}


   AND l.task_id = #{q.taskId}

 GROUP BY DATE(l.created_at + INTERVAL 8 HOUR)
 ORDER BY pointKey

SELECT l.model                                 AS pointKey,
       COALESCE(SUM(l.prompt_tokens), 0)       AS promptTokens,
       COALESCE(SUM(l.completion_tokens), 0)   AS completionTokens,
       COALESCE(SUM(l.cost_micro), 0)          AS costMicro,
       COUNT(*)                                 AS callCount
  FROM llm_call_log l
  LEFT JOIN gen_task gt ON gt.id = l.task_id
 WHERE l.created_at >= #{q.fromUtc}
   AND l.created_at <  #{q.toUtcExclusive}

   AND gt.doc_id = #{q.docId}


   AND l.task_id = #{q.taskId}

 GROUP BY l.model
 ORDER BY pointKey

SELECT COALESCE(SUM(l.cost_micro), 0) AS totalCostMicro
  FROM llm_call_log l
  LEFT JOIN gen_task gt ON gt.id = l.task_id
 WHERE l.created_at >= #{q.fromUtc}
   AND l.created_at <  #{q.toUtcExclusive}

   AND gt.doc_id = #{q.docId}


   AND l.task_id = #{q.taskId}

SELECT COALESCE(SUM(l.prompt_tokens), 0)                                   AS promptTokens,
       COALESCE(SUM(l.completion_tokens), 0)                              AS completionTokens,
       COALESCE(SUM(l.cost_micro), 0)                                     AS costMicro,
       COUNT(*)                                                            AS callCount,
       COALESCE(SUM(CASE WHEN l.error_code LIKE 'E_LLM_PARSE%'
                        THEN 1 ELSE 0 END), 0)                            AS parseFailCount
  FROM llm_call_log l
  LEFT JOIN gen_task gt ON gt.id = l.task_id
 WHERE l.created_at >= #{q.fromUtc}
   AND l.created_at <  #{q.toUtcExclusive}

   AND gt.doc_id = #{q.docId}


   AND l.task_id = #{q.taskId}

SELECT COUNT(*)                                                                        AS totalItems,
       COALESCE(SUM(CASE WHEN gti.attempts = 1 AND gti.status = 'SUCCESS'
                        THEN 1 ELSE 0 END), 0)                                         AS firstPassCount,
       COALESCE(SUM(CASE WHEN gti.status = 'SUCCESS' THEN 1 ELSE 0 END), 0)         AS successCount
  FROM gen_task_item gti
  JOIN gen_task gt ON gt.id = gti.task_id
 WHERE gti.created_at >= #{q.fromUtc}
   AND gti.created_at <  #{q.toUtcExclusive}

   AND gt.doc_id = #{q.docId}


   AND gti.task_id = #{q.taskId}

SELECT gti.latency_ms
  FROM gen_task_item gti
  JOIN gen_task gt ON gt.id = gti.task_id
 WHERE gti.created_at >= #{q.fromUtc}
   AND gti.created_at <  #{q.toUtcExclusive}
   AND gti.status IN ('SUCCESS','FAILED')
   AND gti.latency_ms > 0

   AND gt.doc_id = #{q.docId}


   AND gti.task_id = #{q.taskId}

 ORDER BY gti.latency_ms

SELECT l.model                                                   AS model,
       l.status                                                  AS status,
       COALESCE(SUM(l.prompt_tokens + l.completion_tokens), 0)  AS tokens,
       COUNT(*)                                                  AS callCount
  FROM llm_call_log l
  LEFT JOIN gen_task gt ON gt.id = l.task_id
 WHERE l.created_at >= #{q.fromUtc}
   AND l.created_at <  #{q.toUtcExclusive}

   AND gt.doc_id = #{q.docId}


   AND l.task_id = #{q.taskId}

 GROUP BY l.model, l.status
